package com.example;

public record Order(String id, String customerId, long amount) {
}

package com.example;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class OrderReport {
    public Map<String, List<Order>> byCustomer(List<Order> orders) {
        Map<String, List<Order>> result = new HashMap<>();
        orders.forEach(order -> {
            List<Order> bucket = result.get(order.customerId());
            if (bucket == null) {
                bucket = new ArrayList<>();
                result.put(order.customerId(), bucket);
            }
            bucket.add(order);
        });
        return result;
    }
}

