package com.example;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class OrderReport {
    public Map<String, List<Order>> byCustomer(List<Order> orders) {
        return orders.stream()
                .collect(Collectors.groupingBy(Order::customerId));
    }
}

public Map<String, Long> totalByCustomer(List<Order> orders) {
    return orders.stream()
            .collect(Collectors.groupingBy(Order::customerId,
                    Collectors.summingLong(Order::amount)));
}

import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

public Map<String, Summary> summaryByCustomer(List<Order> orders) {
    return orders.parallelStream()
            .collect(Collectors.groupingBy(Order::customerId, TreeMap::new,
                    Collectors.teeing(
                            Collectors.summingLong(Order::amount),
                            Collectors.counting(),
                            Summary::new)));
}
